#include <stdio.h>

long long reverse_digits(long long n) {
    if (n < 0) n = -n;
    long long rev = 0;
    while (n != 0) {
        rev = rev * 10 + n % 10;
        n /= 10;
    }
    return rev;
}

int main(void) {
    long long n;
    scanf("%lld", &n);
    printf("%lld\n", reverse_digits(n));
    return 0;
}

