#include <stdio.h>

double find_min(double arr[], int n) {
    double m = arr[0];
    int i;
    for (i = 1; i < n; i++) {
        if (arr[i] < m) m = arr[i];
    }
    return m;
}

double find_max(double arr[], int n) {
    double m = arr[0];
    int i;
    for (i = 1; i < n; i++) {
        if (arr[i] > m) m = arr[i];
    }
    return m;
}

double compute_sum(double arr[], int n) {
    double s = 0.0;
    int i;
    for (i = 0; i < n; i++) {
        s += arr[i];
    }
    return s;
}

int main(void) {
    int n, i;
    scanf("%d", &n);
    double arr[1000];
    for (i = 0; i < n; i++) {
        scanf("%lf", &arr[i]);
    }
    double mn = find_min(arr, n);
    double mx = find_max(arr, n);
    double sum = compute_sum(arr, n);
    double avg = sum / n;
    printf("Min: %.2f\n", mn);
    printf("Max: %.2f\n", mx);
    printf("Sum: %.2f\n", sum);
    printf("Avg: %.2f\n", avg);
    return 0;
}

#include <stdio.h>

int is_valid_triangle(int a, int b, int c) {
    return (a + b > c) && (b + c > a) && (a + c > b);
}

double triangle_area(int a, int b, int c) {
    if (!is_valid_triangle(a, b, c)) {
        return 0.0;
    }
    double s = (a + b + c) / 2.0;
    double prod = s * (s - a) * (s - b) * (s - c);
    if (prod <= 0.0) {
        return 0.0;
    }
    double x = prod;
    int i;
    for (i = 0; i < 50; i++) {
        x = 0.5 * (x + prod / x);
    }
    return x;
}

int main(void) {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);
    printf("%.2f\n", triangle_area(a, b, c));
    return 0;
}

