int is_armstrong(int n) {
    if (n < 0) return 0;
    int ndigits = 0;
    int temp = n;
    if (temp == 0) ndigits = 1;
    while (temp != 0) {
        ndigits++;
        temp /= 10;
    }
    int sum = 0;
    temp = n;
    while (temp != 0) {
        int digit = temp % 10;
        int p = 1;
        int i;
        for (i = 0; i < ndigits; i++) {
            p *= digit;
        }
        sum += p;
        temp /= 10;
    }
    return sum == n;
}

int is_perfect(int n) {
    if (n < 2) return 0;
    int sum = 1;
    int i;
    for (i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            sum += i;
            if (i != n / i) {
                sum += n / i;
            }
        }
    }
    return sum == n;
}

int main(void) {
    int n;
    scanf("%d", &n);
    printf("Prime: %s\n", is_prime(n) ? "Yes" : "No");
    printf("Armstrong: %s\n", is_armstrong(n) ? "Yes" : "No");
    printf("Perfect: %s\n", is_perfect(n) ? "Yes" : "No");
    return 0;
}

#include <stdio.h>

int is_leap_year(int y) {
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

int days_in_month(int m, int y) {
    switch (m) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return is_leap_year(y) ? 29 : 28;
        default:
            return 0;
    }
}

int day_of_year(int d, int m, int y) {
    int total = d;
    int i;
    for (i = 1; i < m; i++) {
        total += days_in_month(i, y);
    }
    return total;
}

int main(void) {
    int d, m, y;
    scanf("%d %d %d", &d, &m, &y);
    printf("%d\n", day_of_year(d, m, y));
    return 0;
}
